/* @lc app=leetcode id=2117 lang=kotlin */ class Solution { fun abbreviateProduct(left: Int, right: Int): String = longArrayOf(1L, 0L, 0L).let { L -> doubleArrayOf(1.0).let { D -> (left..right).forEach { n -> L.also { L[0] *= n }.also { D[0] *= n }.also { while (L[0] % 10L == 0L) L[0] = (L[0] / 10L).also { L[1]++ } }.also { if (L[0] >= 1000000000000L) L[0] = (L[0] % 1000000000000L).also { L[2] = 1L } }.also { while (D[0] >= 100000.0) D[0] /= 10.0 } }.run { if (L[2] == 0L && L[0] < 10000000000L) "${L[0]}e${L[1]}" else "${D[0].toInt()}...${(L[0] % 100000L).toString().padStart(5, '0')}e${L[1]}" } } } }